vectorLines :: [String]
vectorLines =
  [
@@VECTOR_LINES@@
  ]

vectors :: String -> [[String]]
vectors kind =
  [ [if field == "-" then "" else field | field <- rest]
  | line <- vectorLines, (first : rest) <- [words line], first == kind ]

unhex :: String -> B.ByteString
unhex text = B.pack (go text)
  where
    go (a : b : rest) = fromIntegral (Char.digitToInt a * 16 + Char.digitToInt b) : go rest
    go _ = []

hex :: B.ByteString -> String
hex = concatMap (\byte -> (if byte < 16 then ('0' :) else id) (Numeric.showHex byte "")) . B.unpack

sha3 :: B.ByteString -> String
sha3 = hex . Crypto.sha3_256

flipped :: B.ByteString -> B.ByteString
flipped bytes = case B.uncons bytes of
  Just (first, rest) -> B.cons (first `Bits.xor` 1) rest
  Nothing -> bytes

